  offset=metadata.get('formalServerLogOffset',initial_log_offset);logpath=BASE/'logs/server.log';length=logpath.stat().st_size-offset
  assert 0<=length<=64*1024**2,'Detailed log size exceeds bound; preserve on Y'
  with logpath.open('rb') as f:f.seek(offset);logs=f.read(length)
